1	import { rulesPresets, type RulesPresetId } from "@pirate-sea-race/content";
2	import {
3	  grantAmount,
4	  itemPrice,
5	  presetRubbings,
6	  presetRubbingTypes,
7	  type RubbingDefinition,
8	  type RubbingType,
9	} from "@pirate-sea-race/content/objectives";
10	import type { LedgerDuel, LedgerPlayer, LedgerState } from "./state.js";
11	
12	/**
13	 * Deeply frozen objects already found to be plain integer data. They cannot change any more, so a later check skips
14	 * them: successive states share most of their structure, and this keeps checking every step cheap.
15	 */
16	const verified = new WeakSet<object>();
17	
18	/**
19	 * What `hashState` needs: plain objects, arrays, strings, booleans, null and safe integers only. Returns the path to
20	 * the first offending value, or null.
21	 */
22	function nonIntegerData(value: unknown): string | null {
23	  if (value === null || typeof value === "string" || typeof value === "boolean") return null;
24	  if (typeof value === "number") return Number.isSafeInteger(value) ? null : ` = ${value}`;
25	  if (typeof value !== "object") return ` is a ${typeof value}`;
26	  if (verified.has(value)) return null;
27	  let deeplyFrozen = Object.isFrozen(value);
28	  const check = (child: unknown, label: string): string | null => {
29	    const found = nonIntegerData(child);
30	    if (found !== null) return `${label}${found}`;
31	    if (typeof child === "object" && child !== null && !verified.has(child)) deeplyFrozen = false;
32	    return null;
33	  };
34	  if (Array.isArray(value)) {
35	    for (let index = 0; index < value.length; index++) {
36	      const found = check(value[index], `[${index}]`);
37	      if (found !== null) return found;
38	    }
39	  } else {
40	    const prototype = Object.getPrototypeOf(value);
41	    if (prototype !== Object.prototype && prototype !== null) return " is not a plain object";
42	    for (const key in value) {
43	      const found = check((value as Record<string, unknown>)[key], `.${key}`);
44	      if (found !== null) return found;
45	    }
46	  }
47	  if (deeplyFrozen) verified.add(value);
48	  return null;
49	}
50	
51	const facts = new Map<RulesPresetId, { expected: RubbingDefinition[]; types: RubbingType[]; expectedTypes: Map<string, RubbingType> }>();
52	
53	function presetFacts(presetId: RulesPresetId) {
54	  let found = facts.get(presetId);
55	  if (found === undefined) {
56	    const preset = rulesPresets[presetId];
57	    const expected = presetRubbings(preset);
58	    found = { expected, types: presetRubbingTypes(preset), expectedTypes: new Map(expected.map((rubbing) => [rubbing.id, rubbing.type])) };
59	    facts.set(presetId, found);
60	  }
61	  return found;
62	}
63	
64	/**
65	 * Every rule the ledger must keep between operations (§4, §12, §19 "Inventory correctness"), as a list of
66	 * violations; empty when the state is sound:
67	 *
68	 * - every rubbing id of the preset is present exactly once, with its type, and no other rubbing exists;
69	 * - each rubbing has one valid location: its own source, a player still in the match, an existing cache, or a
70	 *   reservation for one of the two players of an unresolved duel;
71	 * - no player holds (owns or has reserved) two rubbings of one type;
72	 * - no cache is empty; a player in an unresolved duel owns nothing outside it, is in only one, and has no channel;
73	 * - gold balances are non-negative integers that, with the gold spent, sum to the gold issued (purses and grants);
74	 * - every grant holds its key once and pays the rules' amount; request ids are unique and the purchases add up to
75	 *   the gold spent; a player carries 0 to the carry limit of tonics, one effect at most, and none once gone;
76	 * - the state is plain integer data, so `hashState` covers it.
77	 */
78	export function checkLedger(state: LedgerState): string[] {
79	  const problems: string[] = [];
80	  const offending = nonIntegerData(state);
81	  if (offending !== null) problems.push(`state is not plain integer data: state${offending}`);
82	
83	  const { expected, types, expectedTypes } = presetFacts(state.preset);
84	  if (state.types.join(",") !== types.join(",")) problems.push(`types ${state.types.join(",")} are not the preset's ${types.join(",")}`);
85	
86	  const players = new Map<string, LedgerPlayer>();
87	  for (const player of state.players) {
88	    if (players.has(player.id)) problems.push(`duplicate player id ${player.id}`);
89	    players.set(player.id, player);
90	  }
91	  const sources = new Map(state.sources.map((source) => [source.id, source]));
92	  const caches = new Map<string, number>();
93	  for (const cache of state.caches) {
94	    if (caches.has(cache.id)) problems.push(`duplicate cache id ${cache.id}`);
95	    caches.set(cache.id, 0);
96	  }
97	  const duels = new Map<string, LedgerDuel>();
98	  const unresolved = new Map<string, number>();
99	  for (const duel of state.duels) {
100	    if (duels.has(duel.id)) problems.push(`duplicate duel id ${duel.id}`);
101	    duels.set(duel.id, duel);
102	    if (duel.phase !== "settled") for (const id of duel.players) unresolved.set(id, (unresolved.get(id) ?? 0) + 1);
103	  }
104	
105	  const seen = new Map<string, number>();
106	  const holdings = new Map<string, RubbingType[]>();
107	  for (const rubbing of state.rubbings) {
108	    seen.set(rubbing.id, (seen.get(rubbing.id) ?? 0) + 1);
109	    const type = expectedTypes.get(rubbing.id);
110	    if (type === undefined) problems.push(`rubbing ${rubbing.id} is not one of the preset's`);
111	    else if (rubbing.type !== type) problems.push(`rubbing ${rubbing.id} has type ${rubbing.type}, not ${type}`);
112	    if (rubbing.revision < 0) problems.push(`rubbing ${rubbing.id} has revision ${rubbing.revision}`);
113	
114	    const location = rubbing.location;
115	    const where = `rubbing ${rubbing.id}`;
116	    switch (location.kind) {
117	      case "source": {
118	        const source = sources.get(location.sourceId);
119	        if (!source) problems.push(`${where} is at unknown source ${location.sourceId}`);
120	        else if (source.rubbingId !== rubbing.id) problems.push(`${where} is at ${source.id}, which seals ${source.rubbingId}`);
121	        break;
122	      }
123	      case "player": {
124	        const player = players.get(location.playerId);
125	        if (!player) problems.push(`${where} belongs to unknown player ${location.playerId}`);
126	        else if (player.status === "left") problems.push(`${where} belongs to ${player.id}, who left`);
