27	 * The one place a rubbing is (§4): sealed at its source, owned by a player, held in a recovery cache, or reserved for
28	 * one of the two players inside an unresolved duel.
29	 */
30	export type RubbingLocation =
31	  | { readonly kind: "source"; readonly sourceId: string }
32	  | { readonly kind: "player"; readonly playerId: string }
33	  | { readonly kind: "cache"; readonly cacheId: string }
34	  | { readonly kind: "duel"; readonly duelId: string; readonly playerId: string };
