80	  const { islands, sourcesPerIsland, maxPlayers } = rulesPresets[preset];
81	  const sites = Array.from({ length: islands * sourcesPerIsland }, (_, index) => ({
82	    island: Math.floor(index / sourcesPerIsland),
83	    x: dice.int(50_000),
84	    y: dice.int(50_000),
85	  }));
86	  let state = deepFreeze(createLedger({ preset, seed, sites }));
87	  const stats: Stats = {};
88	  const count = (key: string) => (stats[key] = (stats[key] ?? 0) + 1);
89	  let now = 0;
90	  let joined = 0;
91	  let duelNumber = 0;
92	  const messages: (() => LedgerStep<Outcome>)[] = [];
93	  let requestNumber = 0;
94	  const bought: { requestId: string; playerId: string; item: "rumor" | "tonic" }[] = [];
95	
96	  const apply = <Q, R extends Outcome>(label: string, op: (s: LedgerState, q: Q) => LedgerStep<R>, request: Q): R => {
97	    const before = state;
98	    const { state: after, result } = op(before, request);
99	    count("operations");
100	    count(`${label}:${result.ok ? "ok" : result.rejection}`);
101	    if (result.status) count(`status:${result.status}`);
102	    if (!check) {
103	      state = after;
104	      return result;
105	    }
106	    const problems = checkLedger(after);
107	    if (problems.length > 0) throw new Error(`seed ${seed}, ${label} ${JSON.stringify(request)}:\n${problems.join("\n")}`);
108	    if (!result.ok && after !== before) throw new Error(`${label} was rejected (${result.rejection}) but changed the state`);
109	    economyCheck(after, label);
110	    const moved = new Set<string>();
111	    for (const transfer of result.transfers ?? []) {
112	      if (moved.has(transfer.rubbingId)) throw new Error(`${label} moved ${transfer.rubbingId} twice`);
113	      moved.add(transfer.rubbingId);
114	      const rubbing = findRubbing(after, transfer.rubbingId)!;
115	      expect(rubbing.location).toEqual(transfer.to);
116	      expect(rubbing.revision).toBe(transfer.revisionAfter);
117	      expect(transfer.revisionAfter).toBe(transfer.revisionBefore + 1);
118	      expect(findRubbing(before, transfer.rubbingId)!.location).toEqual(transfer.from);
119	    }
120	    state = deepFreeze(after);
121	    return result;
122	  };
123	
124	  /** §11's economy after every step, stated directly rather than only through `checkLedger`. */
125	  const economyCheck = (after: LedgerState, label: string) => {
126	    let balances = 0;
127	    for (const player of after.players) {
128	      balances += player.gold;
129	      // One effect slot per player, so at most one tonic is active: the slot must be the one activation that fits.
130	      const effect = player.tonicEffect;
131	      const oneEffect = effect === null || effect.endTick - effect.startTick === after.rules.tonicTicks;
132	      if (player.gold < 0 || player.tonics < 0 || player.tonics > after.rules.tonicCarryLimit || !oneEffect) {
133	        throw new Error(`seed ${seed}, ${label}: player ${player.id} has ${player.gold} gold, ${player.tonics} tonics, ${JSON.stringify(effect)}`);
134	      }
135	    }
136	    if (balances + after.goldSpent !== after.goldIssued) throw new Error(`seed ${seed}, ${label}: gold is not accounted for`);
137	  };
138	
139	  const players = () => state.players.map((player) => player.id);
140	  const present = () => state.players.filter((player) => player.status !== "left").map((player) => player.id);
141	  /** Mostly a player still in the match; sometimes one who left, or an unknown id. */
142	  const anyPlayer = () => {
143	    const roll = dice.int(100);
144	    if (roll < 88 && present().length > 0) return dice.pick(present());
145	    if (roll < 97 && players().length > 0) return dice.pick(players());
146	    return "ghost";
147	  };
148	  const idle = () => present().filter((id) => activeDuelOf(state, id) === undefined);
149	  const position = () => ({ x: dice.int(50_000), y: dice.int(50_000) });
150	
151	  /** A run of world ticks: the clock advances and each channelling player holds on, now and then letting go a tick. */
152	  const ticks = () => {
153	    for (let burst = 1 + dice.int(20); burst > 0; burst--) {
154	      now += 1;
155	      // The room advances every tick; here only when a choice window is due, or at random, to keep the test quick.
156	      const due = state.duels.some((duel) => duel.phase === "choosing" && duel.choiceDeadline! <= now);
157	      if (due || dice.percent(10)) {
158	        const advanced = apply("advance", advanceLedger, { tick: now });
159	        for (const duel of advanced.settled) count(`default-theft:${duel.settlement!.stolenType === null ? "none" : "type"}`);
160	      }
161	      for (const player of state.players) {
162	        if (player.channel !== null && !dice.percent(0.3)) {
163	          const progress = apply("progress", progressChannel, { playerId: player.id, tick: now });
164	          if (progress.status === "claimed" || progress.status === "collected") {
165	            expect(findRubbing(state, progress.rubbingId!)!.location).toEqual({ kind: "player", playerId: player.id });
166	          }
167	        }
168	      }
169	    }
170	  };
171	
172	  const actions: [number, () => void][] = [
173	    [40, ticks],
174	    [1, () => {
175	      now += 1 + dice.int(1500);
176	      apply("advance", advanceLedger, { tick: now });
177	    }],
178	    [3, () => {
179	      const fresh = present().length < maxPlayers && dice.percent(90);
180	      apply("join", addPlayer, { playerId: fresh ? `p${++joined}` : anyPlayer(), tick: now, gold: dice.percent(20) ? dice.int(400) : undefined });
181	    }],
182	    [4, () => {
183	      const playerId = anyPlayer();
184	      const held = new Set(findPlayer(state, playerId) ? heldTypes(state, playerId) : []);
185	      const sealed = state.sources.filter((source) => findRubbing(state, source.rubbingId)!.location.kind === "source");
186	      const useful = sealed.filter((source) => !held.has(source.type));
187	      const already = sealed.filter((source) => held.has(source.type));
188	      const roll = dice.int(100);
189	      const source =
190	        roll < 65 && useful.length > 0 ? dice.pick(useful) : roll < 80 && already.length > 0 ? dice.pick(already) : dice.pick(state.sources);
191	      apply("start-collect", startCollect, { playerId, sourceId: dice.percent(97) ? source.id : "source-99-9", tick: now });
192	    }],
193	    [4, () => {
194	      const playerId = anyPlayer();
195	      if (state.caches.length === 0) return;
196	      const cache = dice.pick(state.caches);
197	      const held = new Set(findPlayer(state, playerId) ? heldTypes(state, playerId) : []);
198	      const inside = cacheRubbings(state, cache.id);
199	      const wanted = inside.filter((rubbing) => !held.has(rubbing.type));
200	      const rubbing = dice.percent(80) && wanted.length > 0 ? dice.pick(wanted) : dice.pick(state.rubbings);
201	      apply("start-claim", startCacheClaim, { playerId, cacheId: cache.id, rubbingId: rubbing.id, tick: now });
202	    }],
203	    [1, () => apply("cancel", cancelChannel, { playerId: anyPlayer(), tick: now })],
204	    [2, () => {
205	      // A rival starts on the same rubbing someone is already channelling: only one of them may get it.
206	      const channelling = state.players.filter((player) => player.channel !== null);
207	      const rivals = idle().filter((id) => findPlayer(state, id)!.status === "connected" && findPlayer(state, id)!.channel === null);
208	      if (channelling.length === 0 || rivals.length === 0) return;
209	      const channel = dice.pick(channelling).channel!;
210	      const playerId = dice.pick(rivals);
211	      if (channel.kind === "collect") apply("contest-collect", startCollect, { playerId, sourceId: channel.sourceId, tick: now });
212	      else apply("contest-claim", startCacheClaim, { playerId, cacheId: channel.cacheId, rubbingId: channel.rubbingId, tick: now });
213	    }],
214	    [4, () => {
215	      if (players().length < 2) return;
216	      const reuse = dice.percent(5) && duelNumber > 0;
217	      const duelId = reuse ? `d${1 + dice.int(duelNumber)}` : `d${++duelNumber}`;
218	      const free = idle();
219	      const pair = free.length >= 2 && dice.percent(85) ? [dice.pick(free), dice.pick(free)] : [anyPlayer(), anyPlayer()];
220	      const request = { duelId, players: [pair[0]!, pair[1]!] as const, tick: now };
221	      apply("reserve", reserveDuel, request);
222	      messages.push(() => reserveDuel(state, { ...request, tick: now }));
223	    }],
224	    [4, () => {
225	      const open = state.duels.filter((duel) => duel.phase === "fighting");
226	      const duel = dice.percent(90) && open.length > 0 ? dice.pick(open) : state.duels.length > 0 ? dice.pick(state.duels) : undefined;
227	      if (!duel) return;
228	      const roll = dice.int(100);
229	      const request =
230	        roll < 75
231	          ? { duelId: duel.id, tick: now, outcome: "win" as const, winner: dice.percent(95) ? dice.pick(duel.players) : anyPlayer() }
232	          : roll < 95
233	            ? { duelId: duel.id, tick: now, outcome: "draw" as const }
234	            : { duelId: duel.id, tick: now, outcome: "cancelled" as const };
235	      const result = apply("result", reportDuelResult, request);
236	      if (result.ok && result.duel!.phase === "settled" && request.outcome === "win") count("settled-without-choice");
237	      messages.push(() => reportDuelResult(state, { ...request, tick: now }));
238	    }],
239	    [4, () => {
240	      const choosing = state.duels.filter((duel) => duel.phase === "choosing");
241	      if (choosing.length === 0) return;
242	      const duel = dice.pick(choosing);
243	      const eligible = eligibleTheftTypes(state, duel.id);
244	      const type = dice.percent(80) && eligible.length > 0 ? dice.pick(eligible) : dice.pick(state.types);
245	      const playerId = dice.percent(80) ? duel.result!.winner! : dice.pick(duel.players);
246	      const request = { duelId: duel.id, playerId, type, tick: now };
247	      const result = apply("choose", chooseTheft, request);
248	      if (result.ok) count(`chosen-theft:${result.duel!.settlement!.stolenType === null ? "none" : "type"}`);
249	      messages.push(() => chooseTheft(state, { ...request, tick: now }));
250	    }],
251	    [3, () => {
252	      if (messages.length === 0) return;
253	      const replay = dice.pick(messages);
254	      const before = state;
255	      const { state: after, result } = replay();
256	      count("operations");
257	      count(`repeat:${result.ok ? "ok" : result.rejection}`);
258	      if (check) {
259	        expect(checkLedger(after)).toEqual([]);
260	        if (!result.ok) expect(after).toBe(before);
261	      }
262	      state = check ? deepFreeze(after) : after;
263	    }],
264	    [2, () => apply("disconnect", disconnectPlayer, { playerId: anyPlayer(), tick: now })],
265	    [2, () => apply("reconnect", reconnectPlayer, { playerId: anyPlayer(), tick: now })],
266	    [2, () => {
267	      const waiting = state.players.filter((player) => player.status === "disconnected");
268	      const target = waiting.length > 0 && dice.percent(80) ? dice.pick(waiting) : undefined;
269	      if (target && dice.percent(60)) now = Math.max(now, target.reservationDeadline!);
270	      const result = apply("expire", expireReservation, { playerId: target?.id ?? anyPlayer(), tick: now, position: position() });
271	      if (result.ok && result.duel) count("expire-in-duel");
272	    }],
273	    [1, () => {
274	      const result = apply("quit", quitPlayer, { playerId: anyPlayer(), tick: now, position: position() });
275	      if (result.ok && result.duel) count(`quit-in-duel:${result.duel.phase}`);
276	    }],
277	    [2, () => apply("unlock", unlockSource, { sourceId: dice.pick(state.sources).id, tick: now })],
278	    [1, () => {
279	      if (state.tick === 0) return;
280	      const stale = state.tick - 1 - dice.int(Math.min(state.tick, 20));
281	      const result = apply("stale", addPlayer, { playerId: `late${stale}`, tick: stale });
282	      expect(result.rejection).toBe("stale-tick");
283	    }],
284	  ];
285	  const total = actions.reduce((sum, [weight]) => sum + weight, 0);
286	
287	  /**
288	   * §11's economy draws from its own dice between the steps above. Gold and tonics never steer those steps' draws,
289	   * so the match around the economy is the same sequence it was before the economy existed.
290	   */
291	  const shop = new Dice(seed ^ 0xc01d);
292	  const shopper = () => {
293	    const roll = shop.int(100);
294	    if (roll < 88 && present().length > 0) return shop.pick(present());
295	    if (roll < 97 && players().length > 0) return shop.pick(players());
296	    return "ghost";
297	  };
298	  const economy: [number, () => void][] = [
299	    [4, () => {
300	      // Ruins are keyed per player, supply caches once per match; a small pool of keys makes repeats common.
301	      const reason = shop.percent(50) ? ("ruin" as const) : ("supply-cache" as const);
302	      const sourceKey = reason === "ruin" ? `ruin-${shop.int(4)}` : `supply-${shop.int(4)}`;
303	      apply(`grant-${reason}`, grantGold, { playerId: shopper(), reason, sourceKey, tick: now });
304	    }],
305	    [4, () => {
306	      const roll = shop.int(100);
307	      if (roll < 25 && bought.length > 0) {
308	        // A retry of an earlier purchase: the original result, no charge. Now and then the id is reused wrongly.
309	        const earlier = shop.pick(bought);
310	        const request = shop.percent(85) ? earlier : { ...earlier, playerId: shopper(), item: shop.pick(["rumor", "tonic"] as const) };
311	        const before = state;
312	        const result = apply("rebuy", purchase, { ...request, tick: shop.percent(50) ? now : 0 });
313	        if (result.replayed) {
314	          count("purchase-replayed");
315	          expect(state).toBe(before);
316	          expect(result.purchase?.requestId).toBe(earlier.requestId);
317	        }
318	        return;
